INSERT INTO `products` VALUES (1,1,'iPhone 17 Pro Max','iphone-17-pro-max-256gb','ip17pm-4.jpg','ip17pm-4.jpg',36490000,31010000,50,3,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.9 inch, LTPO Super Retina XDR OLED, 120Hz (ProMotion)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Độ s&aacute;ng</strong></td>\r\n			<td>1600 nits (HDR), <strong>3200 nits</strong> (đỉnh ngo&agrave;i trời)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Apple A19 Pro (Tiến tr&igrave;nh 2nm si&ecirc;u tiết kiệm điện)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>RAM</strong></td>\r\n			<td><strong>12GB</strong> (Tối ưu cho Apple Intelligence)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Bộ nhớ trong</strong></td>\r\n			<td>256GB (Tốc độ đọc ghi chuẩn NVMe mới)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera sau</strong></td>\r\n			<td>Ch&iacute;nh 48MP + G&oacute;c si&ecirc;u rộng 48MP + Telephoto tiềm vọng 48MP (Zoom 5x)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Pin</strong></td>\r\n			<td>Thời lượng xem video l&ecirc;n đến <strong>35 giờ</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Kết nối</strong></td>\r\n			<td>USB-C (USB 3.2 Gen 2), Wi-Fi 7, Modem 5G Apple C1X</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Trọng lượng</strong></td>\r\n			<td>Xấp xỉ 225g (Khung Titan cấp độ 5)</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của iPhone 17 Pro Max</strong></h2>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh 6.9 inch si&ecirc;u lớn với viền mỏng kỷ lục</strong></h3>\r\n\r\n<p>Nhờ c&ocirc;ng nghệ hiển thị mới, iPhone 17 Pro Max sở hữu kh&ocirc;ng gian hiển thị rộng r&atilde;i hơn nhưng k&iacute;ch thước tổng thể kh&ocirc;ng thay đổi qu&aacute; nhiều so với thế hệ cũ. Lớp k&iacute;nh <strong>Ceramic Shield 2</strong> kết hợp với độ s&aacute;ng <strong>3200 nits</strong> gi&uacute;p m&agrave;n h&igrave;nh trở n&ecirc;n bất bại trước mọi điều kiện &aacute;nh s&aacute;ng v&agrave; va đập.</p>\r\n\r\n<h3><strong>Kỷ nguy&ecirc;n Apple Intelligence với RAM 12GB</strong></h3>\r\n\r\n<p>Với việc n&acirc;ng cấp RAM l&ecirc;n <strong>12GB</strong>, c&aacute;c t&iacute;nh năng tr&iacute; tuệ nh&acirc;n tạo như Siri thế hệ mới, dịch thuật thời gian thực v&agrave; chỉnh sửa ảnh th&ocirc;ng minh đều được xử l&yacute; ngay tr&ecirc;n thiết bị. Chip A19 Pro kh&ocirc;ng chỉ mang lại hiệu năng đồ họa khủng khiếp cho gaming m&agrave; c&ograve;n t&iacute;ch hợp hệ thống tản nhiệt mới gi&uacute;p m&aacute;y lu&ocirc;n m&aacute;t mẻ.</p>\r\n\r\n<h3><strong>Hệ thống Camera 48MP &quot;Triple-Threat&quot;</strong></h3>\r\n\r\n<p>Lần đầu ti&ecirc;n, cả 3 ống k&iacute;nh (Ch&iacute;nh, G&oacute;c rộng v&agrave; Tele) đều đạt độ ph&acirc;n giải <strong>48MP</strong>.</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Ống k&iacute;nh Tele 5x:</strong> Cho ph&eacute;p chụp ảnh xa với độ chi tiết cực cao, hỗ trợ zoom kỹ thuật số l&ecirc;n đến 25x với thuật to&aacute;n AI tăng cường.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Camera Control 2.0:</strong> N&uacute;t điều khiển cảm ứng lực thế hệ mới gi&uacute;p bạn thay đổi ti&ecirc;u cự, phơi s&aacute;ng v&agrave; lấy n&eacute;t chỉ bằng c&aacute;c thao t&aacute;c vuốt chạm tinh tế như tr&ecirc;n m&aacute;y ảnh Leica.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3><strong>Thời lượng pin ph&aacute; vỡ mọi kỷ lục</strong></h3>\r\n\r\n<p>Kết hợp giữa vi&ecirc;n pin dung lượng lớn v&agrave; chip A19 Pro tiết kiệm điện, iPhone 17 Pro Max c&oacute; thể duy tr&igrave; hoạt động bền bỉ suốt 2 ng&agrave;y với c&aacute;c t&aacute;c vụ th&ocirc;ng thường. C&ocirc;ng nghệ sạc nhanh mới gi&uacute;p nạp lại <strong>50% pin chỉ trong v&ograve;ng 20 ph&uacute;t</strong>.</p>\r\n\r\n<h3><strong>Face ID dưới m&agrave;n h&igrave;nh v&agrave; Dynamic Island nhỏ gọn</strong></h3>\r\n\r\n<p>Cảm biến Face ID đ&atilde; được Apple thu gọn đ&aacute;ng kể v&agrave; ẩn một phần dưới m&agrave;n h&igrave;nh, gi&uacute;p khu vực <strong>Dynamic Island</strong> trở n&ecirc;n tinh tế hơn, mang lại kh&ocirc;ng gian hiển thị trọn vẹn hơn cho người d&ugrave;ng khi xem phim hoặc chơi game.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Tại sao n&ecirc;n chọn iPhone 17 Pro Max 256GB?</strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Trải nghiệm giải tr&iacute; tốt nhất:</strong> M&agrave;n h&igrave;nh lớn nhất v&agrave; hệ thống loa k&eacute;p sống động nhất trong thế giới iPhone.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Lưu trữ th&ocirc;ng minh:</strong> 256GB l&agrave; mức dung lượng l&yacute; tưởng để c&agrave;i đặt h&agrave;ng loạt ứng dụng nặng v&agrave; lưu trữ video 4K m&agrave; vẫn tối ưu được chi ph&iacute; đầu tư ban đầu.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>T&iacute;nh chuy&ecirc;n nghiệp:</strong> D&agrave;nh cho những ai sử dụng iPhone như một c&ocirc;ng cụ l&agrave;m việc ch&iacute;nh, từ xử l&yacute; văn bản, dựng clip ngắn đến quản l&yacute; kinh doanh.</p>\r\n	</li>\r\n</ul>\r\n','iPhone 17 Pro Max 256GB là định nghĩa mới về sự sang trọng và sức mạnh tối thượng. Sở hữu màn hình lớn nhất từ trước đến nay với kích thước 6.9 inch và viền màn hình siêu mỏng, thiết bị mang lại trải nghiệm thị giác vô cực. Được trang bị chip A19 Pro tiến trình 2nm và hệ thống camera 48MP toàn diện, máy không chỉ xử lý mượt mà mọi tác vụ AI phức tạp mà còn là một máy quay phim chuyên nghiệp trong lòng bàn tay. Phiên bản 256GB là sự lựa chọn cân bằng, đáp ứng hoàn hảo nhu cầu lưu trữ dữ liệu và sáng tạo nội dung chất lượng cao.',3,3,'2026-04-22 15:57:54','2026-04-23 13:50:52','1','1','1',1,1,'Vàng, Xanh, Bạc','256GB, 512GB, 1TB'),(2,2,'Samsung Galaxy S26 Ultra','samsung-galaxy-s26-ultra','s24u-xam.jpg','s24u-xam.jpg#s24u-den.jpg#s24u-tim.jpg#s24u-vang.jpg',36990000,31440000,45,1,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.9 inch, Dynamic AMOLED 2X QHD+, 1-144Hz, độ s&aacute;ng <strong>2600 nits</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Snapdragon 8 Elite Gen 5 for Galaxy (Tiến tr&igrave;nh 3nm)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>RAM / ROM</strong></td>\r\n			<td>12GB/16GB RAM; 256GB / 512GB / 1TB ROM</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera ch&iacute;nh</strong></td>\r\n			<td><strong>200MP (f/1.4)</strong>, OIS, lấy n&eacute;t Laser, ProVisual Engine</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hệ thống Tele</strong></td>\r\n			<td>50MP (Zoom quang 5x, f/2.9) + 10MP (Zoom quang 3x, f/2.4)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera g&oacute;c si&ecirc;u rộng</strong></td>\r\n			<td>50MP (f/1.9), hỗ trợ lấy n&eacute;t Dual Pixel</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Pin &amp; Sạc</strong></td>\r\n			<td>5.000 mAh; Sạc nhanh c&oacute; d&acirc;y <strong>60W</strong>, sạc kh&ocirc;ng d&acirc;y 25W</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Độ mỏng / Trọng lượng</strong></td>\r\n			<td><strong>7.9 mm</strong> / 214 g</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hệ điều h&agrave;nh</strong></td>\r\n			<td>One UI 8.5 (Dựa tr&ecirc;n Android 16), hỗ trợ cập nhật 7 năm</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của Galaxy S26 Ultra</strong></h2>\r\n\r\n<h3><strong>Thiết kế mỏng nhất lịch sử d&ograve;ng Ultra</strong></h3>\r\n\r\n<p>Samsung đ&atilde; th&agrave;nh c&ocirc;ng trong việc giảm độ d&agrave;y của m&aacute;y xuống c&ograve;n <strong>7.9mm</strong> (so với 8.2mm của thế hệ trước) m&agrave; kh&ocirc;ng l&agrave;m giảm dung lượng pin. C&aacute;c cạnh viền được tinh chỉnh để tạo ra sự liền mạch giữa khung nh&ocirc;m v&agrave; mặt k&iacute;nh, mang lại vẻ ngo&agrave;i tinh tế v&agrave; cảm gi&aacute;c cầm nắm v&ocirc; c&ugrave;ng thoải m&aacute;i.</p>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh Privacy Display độc đ&aacute;o</strong></h3>\r\n\r\n<p>Lần đầu ti&ecirc;n, Samsung giới thiệu lớp hiển thị bảo mật t&iacute;ch hợp sẵn. Khi k&iacute;ch hoạt, m&agrave;n h&igrave;nh sẽ tự động giới hạn g&oacute;c nh&igrave;n, gi&uacute;p ngăn chặn những &aacute;nh nh&igrave;n t&ograve; m&ograve; từ ph&iacute;a b&ecirc;n cạnh trong khi bạn đang ở nơi c&ocirc;ng cộng hoặc phương tiện giao th&ocirc;ng, bảo vệ tuyệt đối th&ocirc;ng tin c&aacute; nh&acirc;n.</p>\r\n\r\n<h3><strong>Camera 200MP &quot;Brightest&quot; &ndash; Thống trị b&oacute;ng đ&ecirc;m</strong></h3>\r\n\r\n<p>Với khẩu độ lớn nhất từ trước đến nay tr&ecirc;n d&ograve;ng Ultra (<strong>f/1.4</strong>), camera ch&iacute;nh của S26 Ultra c&oacute; thể thu s&aacute;ng tốt hơn tới 47% so với đời cũ. C&ocirc;ng nghệ <strong>ProVisual Engine</strong> mới sử dụng AI để khử nhiễu đa khung h&igrave;nh v&agrave; tăng cường độ chi tiết, cho ph&eacute;p bạn quay video 8K v&agrave; chụp ảnh ch&acirc;n dung đ&ecirc;m với chất lượng như m&aacute;y ảnh chuy&ecirc;n nghiệp.</p>\r\n\r\n<h3><strong>Galaxy AI 2.0 &amp; Photo Assist</strong></h3>\r\n\r\n<p>Tr&iacute; tuệ nh&acirc;n tạo giờ đ&acirc;y kh&ocirc;ng chỉ dừng lại ở việc chỉnh sửa, m&agrave; c&ograve;n mang t&iacute;nh s&aacute;ng tạo:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Creative Studio:</strong> Chỉ cần m&ocirc; tả hoặc ph&aacute;c thảo, AI sẽ biến h&igrave;nh ảnh của bạn th&agrave;nh một t&aacute;c phẩm nghệ thuật hoặc thay đổi ho&agrave;n to&agrave;n phong c&aacute;ch trang phục của chủ thể trong ảnh.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Now Brief:</strong> Tự động tổng hợp lịch tr&igrave;nh, vị tr&iacute; v&agrave; c&aacute;c th&ocirc;ng b&aacute;o quan trọng nhất cho ng&agrave;y mới của bạn dựa tr&ecirc;n th&oacute;i quen c&aacute; nh&acirc;n.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>T&iacute;ch hợp S-Pen th&ocirc;ng minh:</strong> B&uacute;t S-Pen giờ đ&acirc;y hỗ trợ c&aacute;c cử chỉ AI mới, cho ph&eacute;p bạn tr&iacute;ch xuất dữ liệu từ bất kỳ v&ugrave;ng n&agrave;o tr&ecirc;n m&agrave;n h&igrave;nh chỉ bằng một v&ograve;ng tr&ograve;n.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3><strong>Hiệu năng v&agrave; Kết nối tương lai</strong></h3>\r\n\r\n<p>Sự kết hợp giữa chip Snapdragon 8 Elite Gen 5 v&agrave; chuẩn RAM LPDDR5X mới gi&uacute;p S26 Ultra xử l&yacute; c&aacute;c t&aacute;c vụ đa nhiệm v&agrave; gaming ở mức đồ họa cao nhất một c&aacute;ch mượt m&agrave;. M&aacute;y cũng hỗ trợ chuẩn <strong>Wi-Fi 7</strong> v&agrave; <strong>Bluetooth 6.0</strong>, đảm bảo tốc độ truyền tải dữ liệu nhanh v&agrave; ổn định nhất.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Tại sao n&ecirc;n chọn Galaxy S26 Ultra?</strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>D&agrave;nh cho doanh nh&acirc;n &amp; Nh&agrave; s&aacute;ng tạo:</strong> Sự kết hợp ho&agrave;n hảo giữa S-Pen v&agrave; m&agrave;n h&igrave;nh Privacy Display gi&uacute;p l&agrave;m việc an to&agrave;n, hiệu quả ở mọi nơi.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Người đam m&ecirc; nhiếp ảnh:</strong> Hệ thống camera quad-camera với khả năng zoom 100x v&agrave; chụp đ&ecirc;m kh&ocirc;ng đối thủ.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Gi&aacute; trị sử dụng bền vững:</strong> Cam kết hỗ trợ phần mềm đến năm 2033 v&agrave; khung vỏ si&ecirc;u bền gi&uacute;p m&aacute;y lu&ocirc;n như mới qua thời gian.</p>\r\n	</li>\r\n</ul>\r\n','Samsung Galaxy S26 Ultra là biểu tượng của sự hoàn mỹ và sức mạnh công nghệ năm 2026. Với thiết kế thân máy siêu mỏng chỉ 7.9mm và khung Armor Aluminum siêu bền, thiết bị mang lại cảm giác cầm nắm sang trọng bậc nhất. S26 Ultra sở hữu sức mạnh từ chip Snapdragon 8 Elite Gen 5 tùy chỉnh, màn hình tích hợp lớp bảo mật riêng tư Privacy Display độc đáo và hệ thống camera 200MP được nâng cấp mạnh mẽ về khẩu độ để thống trị nhiếp ảnh đêm. Đây là thiết bị tối thượng dành cho những ai tìm kiếm trải nghiệm AI trực quan và chuyên nghiệp nhất.',2,2,'2026-04-22 15:57:54','2026-04-23 13:49:54','1','1','1',1,1,'X?m Titan, ?en Titan, T?m Titan, V?ng Titan','256GB, 512GB, 1TB'),(3,1,'iPhone 17 Pro','iphone-17-pro-256gb','ip17p-4.jpg','ip17p-4.jpg',33090000,28120000,60,2,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.3 inch, Super Retina XDR OLED, ProMotion 1-120Hz</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Độ s&aacute;ng</strong></td>\r\n			<td>1000 nits (thường), 1600 nits (HDR), <strong>3000 nits</strong> (đỉnh ngo&agrave;i trời)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Apple A19 Pro (Tiến tr&igrave;nh 3nm thế hệ mới), GPU 6 l&otilde;i</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>RAM</strong></td>\r\n			<td><strong>12GB</strong> (Tối ưu h&oacute;a cho c&aacute;c t&aacute;c vụ AI v&agrave; Gaming)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera sau</strong></td>\r\n			<td>Hệ thống 3 camera 48MP: Ch&iacute;nh, G&oacute;c si&ecirc;u rộng v&agrave; Telephoto (Zoom quang 5x)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera trước</strong></td>\r\n			<td>24MP với c&ocirc;ng nghệ Face ID dưới m&agrave;n h&igrave;nh (cải tiến)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Kết nối</strong></td>\r\n			<td>Wi-Fi 7, Modem 5G Apple C1X ch&iacute;nh chủ, Bluetooth 5.4</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Sạc &amp; Pin</strong></td>\r\n			<td>Sạc nhanh 40W qua cổng USB-C, hỗ trợ MagSafe v&agrave; sạc kh&ocirc;ng d&acirc;y Qi2</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của iPhone 17 Pro</strong></h2>\r\n\r\n<h3><strong>Chip A19 Pro v&agrave; 12GB RAM &ndash; Hiệu năng kh&ocirc;ng giới hạn</strong></h3>\r\n\r\n<p>Lần đầu ti&ecirc;n d&ograve;ng Pro được n&acirc;ng cấp l&ecirc;n <strong>12GB RAM</strong>, gi&uacute;p khả năng đa nhiệm v&agrave; xử l&yacute; c&aacute;c m&ocirc; h&igrave;nh ng&ocirc;n ngữ lớn (LLM) của Apple Intelligence diễn ra ngay tr&ecirc;n thiết bị với tốc độ tức th&igrave;. Chip A19 Pro kh&ocirc;ng chỉ mạnh hơn 15% m&agrave; c&ograve;n t&iacute;ch hợp hệ thống tản nhiệt <strong>buồng hơi (Vapor Chamber)</strong>, gi&uacute;p m&aacute;y duy tr&igrave; hiệu năng đỉnh cao khi chơi c&aacute;c tựa game AAA m&agrave; kh&ocirc;ng bị n&oacute;ng.</p>\r\n\r\n<h3><strong>Camera Control 2.0: Điều khiển như m&aacute;y ảnh chuy&ecirc;n nghiệp</strong></h3>\r\n\r\n<p>N&uacute;t <strong>Điều khiển Camera</strong> thế hệ mới nhạy hơn v&agrave; t&iacute;ch hợp th&ecirc;m nhiều cử chỉ th&ocirc;ng minh. Bạn c&oacute; thể vuốt để thay đổi khẩu độ, nhấn nhẹ để kh&oacute;a n&eacute;t (Focus Lock) hoặc nhấn giữ để k&iacute;ch hoạt &quot;Thị gi&aacute;c th&ocirc;ng minh&quot; gi&uacute;p nhận diện vật thể v&agrave; t&igrave;m kiếm th&ocirc;ng tin ngay lập tức.</p>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh LTPO 3000 nits si&ecirc;u s&aacute;ng</strong></h3>\r\n\r\n<p>M&agrave;n h&igrave;nh 6.3 inch của iPhone 17 Pro sử dụng tấm nền mới với độ s&aacute;ng đạt mức kỷ lục <strong>3000 nits</strong>, gi&uacute;p bạn xem r&otilde; mọi nội dung dưới &aacute;nh nắng gắt nhất. C&ocirc;ng nghệ Always-On Display được tối ưu h&oacute;a để ti&ecirc;u thụ &iacute;t điện năng hơn, trong khi viền m&agrave;n h&igrave;nh được thu hẹp tối đa tạo cảm gi&aacute;c tr&agrave;n viền thực thụ.</p>\r\n\r\n<h3><strong>Kết nối 5G &quot;Ch&iacute;nh chủ&quot; Apple</strong></h3>\r\n\r\n<p>iPhone 17 Pro trang bị modem 5G do Apple tự thiết kế, mang lại sự đồng bộ tuyệt đối với phần cứng. Kết nối mạng ổn định hơn, tốc độ tải l&ecirc;n/xuống nhanh hơn v&agrave; đặc biệt l&agrave; tiết kiệm pin hơn đ&aacute;ng kể khi sử dụng dữ liệu di động li&ecirc;n tục.</p>\r\n\r\n<h3><strong>M&agrave;u sắc thời thượng v&agrave; vật liệu Titanium</strong></h3>\r\n\r\n<p>Thiết bị tiếp tục sử dụng khung viền <strong>Titanium cấp độ 5</strong> nhưng được xử l&yacute; bề mặt b&oacute;ng bẩy hơn. C&aacute;c t&ugrave;y chọn m&agrave;u sắc mới cho năm 2026 bao gồm: <strong>Cam Vũ Trụ (Cosmic Orange)</strong> ấn tượng, <strong>Xanh Đậm (Deep Blue)</strong> lịch l&atilde;m, c&ugrave;ng c&aacute;c m&agrave;u truyền thống như Bạc v&agrave; Đen Kh&ocirc;ng Gian.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Tại sao n&ecirc;n chọn phi&ecirc;n bản 256GB?</strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Lưu trữ tối ưu:</strong> 256GB l&agrave; mức dung lượng ho&agrave;n hảo để bạn kh&ocirc;ng phải thường xuy&ecirc;n dọn dẹp bộ nhớ hay mua th&ecirc;m iCloud qu&aacute; sớm.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Hỗ trợ quay phim chuy&ecirc;n nghiệp:</strong> Đủ kh&ocirc;ng gian để lưu trữ c&aacute;c đoạn video 4K/60fps chuẩn Dolby Vision d&agrave;i cho c&aacute;c chuyến du lịch hoặc c&ocirc;ng việc s&aacute;ng tạo.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Gi&aacute; trị b&aacute;n lại cao:</strong> C&aacute;c d&ograve;ng iPhone Pro phi&ecirc;n bản 256GB lu&ocirc;n giữ gi&aacute; tốt nhất tr&ecirc;n thị trường m&aacute;y cũ so với bản 128GB (nay đ&atilde; dần trở n&ecirc;n lỗi thời).</p>\r\n	</li>\r\n</ul>\r\n','iPhone 17 Pro 256GB là đỉnh cao công nghệ mới, thiết lập lại tiêu chuẩn cho một chiếc smartphone chuyên nghiệp. Với sức mạnh từ chip A19 Pro tiến trình 2nm siêu tiết kiệm điện và hệ thống camera 48MP Fusion cải tiến, thiết bị mang lại khả năng xử lý AI (Apple Intelligence) mượt mà hơn bao giờ hết. Phiên bản 256GB là sự lựa chọn tối ưu, cung cấp không gian đủ lớn để bạn thỏa sức quay phim ProRes 4K, chụp ảnh ProRAW và lưu trữ kho ứng dụng khổng lồ mà không cần lo lắng về bộ nhớ.',3,3,'2026-04-22 15:57:54','2026-04-23 13:48:59','1','1','1',1,1,'Cam, Xanh, Bạc','256GB, 512GB, 1TB'),(4,2,'Samsung Galaxy S26+','samsung-galaxy-s26','s24p-den.jpg','s24p-den.jpg#s24p-tim.jpg#s24p-vang.jpg',29990000,25490000,40,0,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.7 inch, Dynamic AMOLED 2X, QHD+, 1-120Hz, 3000 nits</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Snapdragon 8 Gen 5 for Galaxy (Tiến tr&igrave;nh 3nm)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>RAM / ROM</strong></td>\r\n			<td>12GB RAM; 256GB / 512GB ROM</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera sau</strong></td>\r\n			<td>Ch&iacute;nh 50MP (OIS) + Tele 12MP (3x) + G&oacute;c si&ecirc;u rộng 12MP</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Pin &amp; Sạc</strong></td>\r\n			<td><strong>4.900 mAh</strong>; Sạc nhanh 45W, Sạc kh&ocirc;ng d&acirc;y 15W</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Kết nối</strong></td>\r\n			<td>Wi-Fi 7, 5G (Sub-6 &amp; mmWave), Bluetooth 5.4</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vật liệu</strong></td>\r\n			<td>Khung Armor Aluminum thế hệ mới, k&iacute;nh Gorilla Glass Victus 3</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hệ điều h&agrave;nh</strong></td>\r\n			<td>One UI 8.1 (Dựa tr&ecirc;n Android 16)</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của Samsung Galaxy S26+</strong></h2>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh QHD+ si&ecirc;u s&aacute;ng v&agrave; sắc n&eacute;t</strong></h3>\r\n\r\n<p>Kh&aacute;c với phi&ecirc;n bản ti&ecirc;u chuẩn, Galaxy S26+ sở hữu độ ph&acirc;n giải <strong>QHD+</strong> tr&ecirc;n k&iacute;ch thước 6.7 inch, mang lại mật độ điểm ảnh cao gi&uacute;p mọi chi tiết h&igrave;nh ảnh đều cực kỳ mịn m&agrave;ng. Độ s&aacute;ng tối đa l&ecirc;n tới <strong>3000 nits</strong> đảm bảo nội dung lu&ocirc;n hiển thị rực rỡ kể cả dưới &aacute;nh nắng gay gắt nhất.</p>\r\n\r\n<h3><strong>Galaxy AI 2.0: Trợ l&yacute; th&ocirc;ng minh đa nhiệm</strong></h3>\r\n\r\n<p>S tận dụng thế mạnh m&agrave;n h&igrave;nh lớn, Galaxy AI tr&ecirc;n S26+ hỗ trợ đắc lực cho c&ocirc;ng việc:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Circle to Search đa năng:</strong> Kh&ocirc;ng chỉ t&igrave;m kiếm h&igrave;nh ảnh, AI c&ograve;n hỗ trợ giải c&aacute;c b&agrave;i to&aacute;n phức tạp hoặc t&oacute;m tắt c&aacute;c văn bản d&agrave;i ngay tr&ecirc;n m&agrave;n h&igrave;nh.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Ghi ch&uacute; th&ocirc;ng minh (Note Assist):</strong> Tự động d&agrave;n trang, sửa lỗi ch&iacute;nh tả v&agrave; t&oacute;m tắt nội dung cuộc họp từ bản ghi &acirc;m sang văn bản một c&aacute;ch chuy&ecirc;n nghiệp.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Chỉnh sửa ảnh chuy&ecirc;n s&acirc;u:</strong> T&iacute;nh năng &quot;Generative Edit&quot; cho ph&eacute;p di chuyển vật thể, lấp đầy ph&ocirc;ng nền một c&aacute;ch tự nhi&ecirc;n bằng sức mạnh của đ&aacute;m m&acirc;y.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3><strong>Hiệu năng mạnh mẽ với Snapdragon 8 Gen 5</strong></h3>\r\n\r\n<p>Con chip Snapdragon thế hệ mới nhất mang lại tốc độ xử l&yacute; nhanh hơn 25% v&agrave; tiết kiệm điện năng hơn 30% so với đời cũ. Hệ thống tản nhiệt buồng hơi tr&ecirc;n d&ograve;ng Plus đ&atilde; được Samsung mở rộng diện t&iacute;ch đ&aacute;ng kể, gi&uacute;p m&aacute;y lu&ocirc;n m&aacute;t mẻ khi bạn chơi c&aacute;c tựa game đồ họa khủng hoặc quay video 8K thời gian d&agrave;i.</p>\r\n\r\n<h3><strong>Thời lượng pin ấn tượng v&agrave; sạc nhanh</strong></h3>\r\n\r\n<p>Với vi&ecirc;n pin <strong>4.900 mAh</strong> tiệm cận d&ograve;ng Ultra, Galaxy S26+ dễ d&agrave;ng đồng h&agrave;nh c&ugrave;ng bạn qua hơn một ng&agrave;y d&agrave;i sử dụng với cường độ cao. C&ocirc;ng nghệ sạc nhanh 45W gi&uacute;p bạn nạp lại 65% pin chỉ trong v&ograve;ng 30 ph&uacute;t, đảm bảo mọi trải nghiệm kh&ocirc;ng bị gi&aacute;n đoạn.</p>\r\n\r\n<h3><strong>Thiết kế phẳng tinh tế, thời thượng</strong></h3>\r\n\r\n<p>Galaxy S26+ sở hữu khung viền nh&ocirc;m si&ecirc;u bền được bo cong nhẹ ở c&aacute;c g&oacute;c để tạo cảm gi&aacute;c cầm nắm chắc chắn, kh&ocirc;ng bị cấn tay d&ugrave; k&iacute;ch thước m&aacute;y kh&aacute; lớn. C&aacute;c t&ugrave;y chọn m&agrave;u sắc mới như <strong>Xanh Titan</strong> hay <strong>T&iacute;m Thạch Anh</strong> mang lại vẻ ngo&agrave;i cực kỳ sang trọng v&agrave; h&uacute;t mắt.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Tại sao n&ecirc;n chọn Galaxy S26+?</strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Kh&ocirc;ng gian lớn, gi&aacute; hợp l&yacute;:</strong> Nếu bạn muốn trải nghiệm m&agrave;n h&igrave;nh to v&agrave; pin tr&acirc;u như d&ograve;ng Ultra nhưng th&iacute;ch thiết kế camera gọn g&agrave;ng v&agrave; mức gi&aacute; dễ tiếp cận hơn.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Khả năng l&agrave;m việc linh hoạt:</strong> Cấu h&igrave;nh mạnh mẽ đ&aacute;p ứng tốt cả nhu cầu chơi game giải tr&iacute; lẫn xử l&yacute; c&aacute;c t&aacute;c vụ đồ họa, văn ph&ograve;ng.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Đầu tư d&agrave;i hạn:</strong> Hỗ trợ cập nhật phần mềm l&ecirc;n đến 7 năm, gi&uacute;p m&aacute;y lu&ocirc;n hoạt động ổn định v&agrave; an to&agrave;n trong thời gian d&agrave;i.</p>\r\n	</li>\r\n</ul>\r\n','Samsung Galaxy S26+ là sự lựa chọn tối ưu cho những người dùng cần một không gian hiển thị rộng rãi nhưng vẫn giữ được thiết kế thanh thoát, mỏng nhẹ. Với màn hình 6.7 inch rực rỡ, dung lượng pin được nâng cấp mạnh mẽ và sự hỗ trợ toàn diện từ Galaxy AI 2.0, S26+ không chỉ phục vụ tốt nhu cầu giải trí đỉnh cao mà còn là một công cụ hỗ trợ công việc đa nhiệm hiệu quả. Chip Snapdragon 8 Gen 5 được tối ưu riêng mang lại hiệu năng dẫn đầu, sẵn sàng thách thức mọi giới hạn của một chiếc smartphone hiện đại.',3,3,'2026-04-22 15:57:54','2026-04-23 13:47:57','1','1','1',1,1,'?en Onyx, T?m Cobalt, V?ng Amber','256GB, 512GB'),(5,4,'Xiaomi 17 Ultra','xiaomi-17-ultra','mi17u-4.jpg','mi17u-4.jpg',29990000,25490000,30,0,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.9 inch, LTPO AMOLED, 2K (2608x1200), 120Hz, 3500 nits</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Qualcomm Snapdragon 8 Elite Gen 5 (Tiến tr&igrave;nh 3nm)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>RAM / ROM</strong></td>\r\n			<td>16GB RAM; 512GB / 1TB ROM (UFS 4.1)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera ch&iacute;nh</strong></td>\r\n			<td>50MP, cảm biến 1-inch (Light Fusion 1050L), khẩu độ f/1.67, OIS</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera Tele</strong></td>\r\n			<td><strong>200MP Leica Periscope</strong>, zoom cơ kh&iacute; 75-100mm, tối đa 400x kỹ thuật số</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera g&oacute;c rộng</strong></td>\r\n			<td>50MP, g&oacute;c nh&igrave;n 115 độ, hỗ trợ chụp Macro 5cm</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Pin &amp; Sạc</strong></td>\r\n			<td><strong>6.000mAh</strong>; Sạc nhanh 90W (d&acirc;y), 50W (kh&ocirc;ng d&acirc;y)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Trọng lượng</strong></td>\r\n			<td>218g (Nhẹ hơn v&agrave; mỏng hơn bản 15 Ultra)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hệ điều h&agrave;nh</strong></td>\r\n			<td>HyperOS 3 (Dựa tr&ecirc;n Android 16)</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của Xiaomi 17 Ultra</strong></h2>\r\n\r\n<h3><strong>Hệ thống Zoom cơ kh&iacute; Leica 200MP đầu ti&ecirc;n</strong></h3>\r\n\r\n<p>Đ&acirc;y l&agrave; điểm đột ph&aacute; lớn nhất của Xiaomi 17 Ultra. Thay v&igrave; d&ugrave;ng c&aacute;c mức zoom kỹ thuật số cố định, ống k&iacute;nh Tele 200MP sử dụng c&aacute;c nh&oacute;m thấu k&iacute;nh di chuyển vật l&yacute; (Cơ kh&iacute;) để thay đổi ti&ecirc;u cự từ <strong>75mm đến 100mm</strong>. Điều n&agrave;y đảm bảo chất lượng h&igrave;nh ảnh ở mọi mức zoom đều l&agrave; quang học thuần t&uacute;y, mang lại độ sắc n&eacute;t kinh ngạc cho ảnh ch&acirc;n dung v&agrave; ảnh chụp xa.</p>\r\n\r\n<h3><strong>Cảm biến ch&iacute;nh 1-inch với c&ocirc;ng nghệ LOFIC HDR</strong></h3>\r\n\r\n<p>Cảm biến ch&iacute;nh 50MP k&iacute;ch thước 1-inch khổng lồ kết hợp với c&ocirc;ng nghệ <strong>LOFIC HDR</strong> mới gi&uacute;p m&aacute;y xử l&yacute; cực tốt c&aacute;c v&ugrave;ng &aacute;nh s&aacute;ng phức tạp. Những bức ảnh chụp ngược s&aacute;ng hoặc chụp đ&ecirc;m sẽ kh&ocirc;ng c&ograve;n bị ch&aacute;y s&aacute;ng ở c&aacute;c v&ugrave;ng qu&aacute; rực, giữ trọn vẹn chi tiết b&oacute;ng đổ v&agrave; &aacute;nh đ&egrave;n rực rỡ.</p>\r\n\r\n<h3><strong>Thiết kế mỏng nhẹ bất chấp pin khủng</strong></h3>\r\n\r\n<p>D&ugrave; dung lượng pin được n&acirc;ng l&ecirc;n mức <strong>6.000mAh</strong> (vượt trội so với c&aacute;c đối thủ c&ugrave;ng ph&acirc;n kh&uacute;c), Xiaomi đ&atilde; th&agrave;nh c&ocirc;ng trong việc giảm độ d&agrave;y m&aacute;y xuống chỉ c&ograve;n <strong>8.29mm</strong>. Khung viền hợp kim nh&ocirc;m cường lực cao cấp kết hợp với mặt lưng bằng sợi thủy tinh tổng hợp gi&uacute;p m&aacute;y đạt chuẩn kh&aacute;ng nước <strong>IP68/IP69</strong>.</p>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh 3500 nits - S&aacute;ng nhất thế giới</strong></h3>\r\n\r\n<p>M&agrave;n h&igrave;nh 6.9 inch tr&ecirc;n 17 Ultra kh&ocirc;ng chỉ lớn hơn m&agrave; c&ograve;n đạt độ s&aacute;ng đỉnh điểm <strong>3500 nits</strong>. C&ocirc;ng nghệ hiển thị 68 tỷ m&agrave;u c&ugrave;ng tần số qu&eacute;t LTPO gi&uacute;p mọi trải nghiệm từ xem phim đến chơi game đều mượt m&agrave; v&agrave; sống động như thật ngay cả dưới nắng gắt.</p>\r\n\r\n<h3><strong>Chip Snapdragon 8 Elite Gen 5 &amp; HyperOS 3</strong></h3>\r\n\r\n<p>Con chip mới nhất từ Qualcomm với xung nhịp l&ecirc;n tới <strong>4.6GHz</strong> gi&uacute;p hiệu suất CPU tăng 20% v&agrave; GPU tăng 23%. Kết hợp với hệ điều h&agrave;nh <strong>HyperOS 3</strong>, m&aacute;y t&iacute;ch hợp s&acirc;u c&aacute;c t&iacute;nh năng AI như: X&oacute;a vật thể video, dịch thuật trực tiếp bằng giọng n&oacute;i v&agrave; trợ l&yacute; s&aacute;ng tạo h&igrave;nh ảnh chuy&ecirc;n nghiệp.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Phụ kiện đặc biệt: Photography Kit</strong></h2>\r\n\r\n<p>Xiaomi 17 Ultra vẫn hỗ trợ bộ phụ kiện tay cầm nhiếp ảnh chuy&ecirc;n dụng. Tay cầm n&agrave;y kh&ocirc;ng chỉ gi&uacute;p bạn cầm m&aacute;y chắc chắn như m&aacute;y ảnh DSLR m&agrave; c&ograve;n t&iacute;ch hợp th&ecirc;m vi&ecirc;n pin <strong>2.000mAh</strong>, n&acirc;ng tổng dung lượng pin l&ecirc;n tới <strong>8.000mAh</strong> cho những ng&agrave;y quay phim d&agrave;i.</p>\r\n\r\n<blockquote>\r\n<p><strong>Lưu &yacute;:</strong> Sản phẩm n&agrave;y hiện đang l&agrave; đối thủ trực tiếp của Galaxy S26 Ultra v&agrave; iPhone 17 Pro Max trong cuộc đua dẫn đầu về nhiếp ảnh di động năm 2026.</p>\r\n</blockquote>\r\n','Xiaomi 17 Ultra là định nghĩa mới về nhiếp ảnh di động chuyên nghiệp. Được trang bị hệ thống ống kính Leica 200MP với khả năng zoom quang học cơ khí độc nhất, thiết bị cho phép thay đổi tiêu cự vật lý mà không làm mất chi tiết ảnh. Với sức mạnh từ chip Snapdragon 8 Elite Gen 5, viên pin khổng lồ 6.000mAh và thiết kế mỏng nhẹ hơn thế hệ trước, Xiaomi 17 Ultra không chỉ là một chiếc điện thoại flagship mà còn là một chiếc máy ảnh chuyên nghiệp thu nhỏ trong túi của bạn.',3,3,'2026-04-22 15:57:54','2026-05-15 23:34:05','1','1','1',1,1,'Đen, Trắng, Đen bạc, Xanh lá','256GB, 512GB, 1TB'),(6,10,'Google Pixel 10 Pro','google-pixel-10-pro','pixel10p-1.jpg','pixel10p-1.jpg',27990000,23800000,35,0,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.8 inch, LTPO OLED Super Actua, 1-120Hz, 3200 nits</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Google Tensor G5 (Thiết kế ho&agrave;n to&agrave;n bởi Google)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>RAM / ROM</strong></td>\r\n			<td>16GB RAM; 256GB / 512GB / 1TB ROM</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera sau</strong></td>\r\n			<td>Ch&iacute;nh 50MP + G&oacute;c si&ecirc;u rộng 48MP + Tele 48MP (Zoom quang 5x)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera trước</strong></td>\r\n			<td>42MP với lấy n&eacute;t tự động Dual Pixel</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Pin &amp; Sạc</strong></td>\r\n			<td>5.100 mAh; Sạc nhanh 45W, sạc kh&ocirc;ng d&acirc;y 23W</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hệ điều h&agrave;nh</strong></td>\r\n			<td>Android 16 (Hỗ trợ cập nhật l&ecirc;n đến 7 năm)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>T&iacute;nh năng an to&agrave;n</strong></td>\r\n			<td>Vệ tinh khẩn cấp (Satellite SOS), Chip bảo mật Titan M3</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của Google Pixel 10 Pro</strong></h2>\r\n\r\n<h3><strong>Chip Tensor G5: Kỷ nguy&ecirc;n mới của sức mạnh</strong></h3>\r\n\r\n<p>Kh&aacute;c với c&aacute;c thế hệ trước, Tensor G5 l&agrave; con chip đầu ti&ecirc;n được Google tự tay thiết kế ho&agrave;n to&agrave;n v&agrave; sản xuất bởi TSMC. Điều n&agrave;y gi&uacute;p Pixel 10 Pro khắc phục triệt để vấn đề nhiệt độ v&agrave; hiệu năng, cho ph&eacute;p m&aacute;y xử l&yacute; c&aacute;c t&aacute;c vụ đồ họa nặng v&agrave; AI phức tạp một c&aacute;ch nhanh ch&oacute;ng, tiết kiệm pin tối đa.</p>\r\n\r\n<h3><strong>Camera AI: Nhiếp ảnh điện to&aacute;n kh&ocirc;ng đối thủ</strong></h3>\r\n\r\n<p>Pixel 10 Pro tiếp tục giữ vững ng&ocirc;i vương chụp ảnh với cụm camera được n&acirc;ng cấp mạnh mẽ:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Video Magic Editor:</strong> Cho ph&eacute;p bạn x&oacute;a vật thể, thay đổi bầu trời hoặc chỉnh sửa &acirc;m thanh trong video bằng AI ngay sau khi quay.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Night Sight Video:</strong> Khả năng quay video trong b&oacute;ng tối r&otilde; n&eacute;t như ban ng&agrave;y nhờ thuật to&aacute;n xử l&yacute; h&igrave;nh ảnh mới nhất.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Super Res Zoom 30x:</strong> Kết hợp giữa ống k&iacute;nh tiềm vọng v&agrave; AI để giữ lại chi tiết cực tốt ở khoảng c&aacute;ch xa.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3><strong>Trải nghiệm AI &quot;Gemini Nano&quot; thế hệ 2</strong></h3>\r\n\r\n<p>Với 16GB RAM chuẩn mới, Pixel 10 Pro c&oacute; thể chạy c&aacute;c m&ocirc; h&igrave;nh ng&ocirc;n ngữ lớn (LLM) ngay tr&ecirc;n m&aacute;y. Bạn c&oacute; thể t&oacute;m tắt t&agrave;i liệu, viết email, hay tạo ảnh từ văn bản chỉ trong t&iacute;ch tắc m&agrave; kh&ocirc;ng cần gửi dữ liệu l&ecirc;n đ&aacute;m m&acirc;y, đảm bảo quyền ri&ecirc;ng tư tuyệt đối.</p>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh Super Actua si&ecirc;u s&aacute;ng</strong></h3>\r\n\r\n<p>M&agrave;n h&igrave;nh của Pixel 10 Pro c&oacute; độ s&aacute;ng kỷ lục l&ecirc;n tới <strong>3200 nits</strong>, gi&uacute;p mọi nội dung hiển thị rực rỡ v&agrave; r&otilde; n&eacute;t ngay cả dưới &aacute;nh nắng gắt nhất. C&ocirc;ng nghệ LTPO thế hệ mới gi&uacute;p m&agrave;n h&igrave;nh phản hồi cực nhanh nhưng vẫn cực kỳ tiết kiệm điện năng.</p>\r\n\r\n<h3><strong>Hỗ trợ phần mềm d&agrave;i nhất thị trường</strong></h3>\r\n\r\n<p>Google cam kết cập nhật hệ điều h&agrave;nh, t&iacute;nh năng mới (Feature Drops) v&agrave; bảo mật cho Pixel 10 Pro trong v&ograve;ng <strong>7 năm</strong>. Điều n&agrave;y đảm bảo chiếc điện thoại của bạn vẫn lu&ocirc;n hiện đại v&agrave; an to&agrave;n cho đến năm 2033.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Tại sao n&ecirc;n chọn Google Pixel 10 Pro?</strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Người y&ecirc;u th&iacute;ch chụp ảnh:</strong> Nếu bạn muốn sở hữu chiếc camera phone th&ocirc;ng minh nhất thế giới.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Trải nghiệm Android thuần khiết:</strong> Kh&ocirc;ng phần mềm r&aacute;c, giao diện tối giản, mượt m&agrave; v&agrave; nhận cập nhật sớm nhất.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>T&iacute;nh bảo mật cao:</strong> Sự kết hợp giữa chip Titan M3 v&agrave; hệ thống VPN t&iacute;ch hợp gi&uacute;p bảo vệ dữ liệu c&aacute; nh&acirc;n của bạn an to&agrave;n nhất.</p>\r\n	</li>\r\n</ul>\r\n','Google Pixel 10 Pro là đỉnh cao của sự thông minh và sức mạnh đồ họa. Đây là thế hệ đầu tiên trang bị chip Tensor G5 – bộ vi xử lý \"thuần Google\" được sản xuất trên tiến trình 3nm tiên tiến nhất, mang lại hiệu năng vượt bậc và khả năng xử lý AI ngay trên thiết bị mà không cần internet. Với hệ thống camera dẫn đầu thị trường và trải nghiệm Android nguyên bản mượt mà, Pixel 10 Pro chính là chiếc smartphone định nghĩa lại cách chúng ta tương tác với trí tuệ nhân tạo hàng ngày.',3,3,'2026-04-22 15:57:54','2026-05-15 23:33:51','1','1','1',1,1,'Đen, Xanh dương, Vàng đồng, Xanh lá','128GB, 256GB, 512GB'),(7,2,'Samsung Galaxy S26','samsung-galaxy-s26','s24-den.jpg','s24-den.jpg#s24-xam.jpg#s24-tim.jpg#s24-vang.jpg',25990000,22090000,100,0,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.3 inch, Dynamic AMOLED 2X, 1-120Hz, độ s&aacute;ng 2800 nits</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Snapdragon 8 Gen 5 (d&agrave;nh ri&ecirc;ng cho Galaxy)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>RAM / ROM</strong></td>\r\n			<td>12GB RAM; 128GB/256GB/512GB ROM</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera sau</strong></td>\r\n			<td>Ch&iacute;nh 50MP (OIS) + Tele 10MP (3x) + G&oacute;c si&ecirc;u rộng 12MP</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera trước</strong></td>\r\n			<td>12MP Dual Pixel AF</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Pin &amp; Sạc</strong></td>\r\n			<td>4.200 mAh; Sạc nhanh 25W, Sạc kh&ocirc;ng d&acirc;y 15W</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Kh&aacute;ng nước</strong></td>\r\n			<td>IP68 (Độ s&acirc;u 1.5m trong 30 ph&uacute;t)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Chất liệu</strong></td>\r\n			<td>Khung nh&ocirc;m Armor Aluminum thế hệ 3, k&iacute;nh Gorilla Glass Victus 3</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của Samsung Galaxy S26</strong></h2>\r\n\r\n<h3><strong>Thiết kế &quot;Phẳng h&oacute;a&quot; hiện đại v&agrave; sang trọng</strong></h3>\r\n\r\n<p>Galaxy S26 sở hữu thiết kế vu&ocirc;ng vức hơn với c&aacute;c cạnh phẳng v&agrave; viền m&agrave;n h&igrave;nh mỏng đều ở cả 4 cạnh, tạo n&ecirc;n sự c&acirc;n đối tuyệt đối. Mặt lưng k&iacute;nh mờ được xử l&yacute; bằng c&ocirc;ng nghệ nano gi&uacute;p hạn chế tối đa dấu v&acirc;n tay v&agrave; mang lại cảm gi&aacute;c cầm nắm cực kỳ b&aacute;m tay.</p>\r\n\r\n<h3><strong>Galaxy AI 2.0: Trải nghiệm th&ocirc;ng minh thế hệ mới</strong></h3>\r\n\r\n<p>Kh&ocirc;ng chỉ dừng lại ở dịch thuật hay chỉnh sửa ảnh, Galaxy AI tr&ecirc;n S26 đ&atilde; tiến l&ecirc;n tầm cao mới:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>H&agrave;nh động dự đo&aacute;n:</strong> AI tự động gợi &yacute; c&aacute;c ứng dụng hoặc thao t&aacute;c tiếp theo dựa tr&ecirc;n vị tr&iacute; v&agrave; thời điểm bạn sử dụng điện thoại.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>T&oacute;m tắt video thời gian thực:</strong> C&oacute; khả năng t&oacute;m tắt nội dung c&aacute;c cuộc họp video hoặc video YouTube ngay khi bạn đang xem.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Studio Ảnh Ch&acirc;n dung AI:</strong> Biến những bức ảnh chụp b&igrave;nh thường th&agrave;nh ảnh nghệ thuật chuy&ecirc;n nghiệp với nhiều phong c&aacute;ch kh&aacute;c nhau chỉ bằng một chạm.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3><strong>Hiệu năng dẫn đầu với Snapdragon 8 Gen 5</strong></h3>\r\n\r\n<p>Sức mạnh của Snapdragon 8 Gen 5 được tối ưu ri&ecirc;ng cho d&ograve;ng Galaxy mang lại hiệu năng CPU vượt trội v&agrave; khả năng xử l&yacute; đồ họa mượt m&agrave; cho mọi tựa game nặng nhất. Hệ thống tản nhiệt buồng hơi được mở rộng gi&uacute;p m&aacute;y duy tr&igrave; nhiệt độ ổn định ngay cả khi quay video 8K hay chơi game li&ecirc;n tục.</p>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh si&ecirc;u s&aacute;ng 2800 nits</strong></h3>\r\n\r\n<p>Tấm nền Dynamic AMOLED 2X thế hệ mới cho ph&eacute;p hiển thị rực rỡ ngay cả dưới nguồn s&aacute;ng cực mạnh. C&ocirc;ng nghệ Vision Booster cải tiến gi&uacute;p t&aacute;i tạo m&agrave;u sắc ch&iacute;nh x&aacute;c, mang lại trải nghiệm xem phim v&agrave; giải tr&iacute; chuẩn điện ảnh.</p>\r\n\r\n<h3><strong>Hệ thống Camera t&iacute;ch hợp cảm biến mới</strong></h3>\r\n\r\n<p>Cụm camera tr&ecirc;n Galaxy S26 được n&acirc;ng cấp về thuật to&aacute;n xử l&yacute; đ&ecirc;m (Nightography). Cảm biến ch&iacute;nh 50MP với khẩu độ lớn gi&uacute;p thu s&aacute;ng tốt hơn, kết hợp c&ugrave;ng AI gi&uacute;p t&aacute;i tạo chi tiết v&agrave; khử nhiễu hiệu quả, mang lại những bức ảnh sắc n&eacute;t trong mọi điều kiện &aacute;nh s&aacute;ng.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Tại sao bạn n&ecirc;n sở hữu Galaxy S26?</strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Lựa chọn cho người th&iacute;ch m&aacute;y nhỏ:</strong> Nếu bạn cần một chiếc m&aacute;y nhỏ gọn, dễ d&agrave;ng sử dụng bằng một tay nhưng vẫn c&oacute; cấu h&igrave;nh của &quot;qu&aacute;i vật&quot;.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Độ bền bỉ l&acirc;u d&agrave;i:</strong> Samsung cam kết hỗ trợ cập nhật hệ điều h&agrave;nh v&agrave; bảo mật l&ecirc;n đến 7 năm, gi&uacute;p m&aacute;y lu&ocirc;n mới mẻ qua thời gian.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Hệ sinh th&aacute;i th&ocirc;ng minh:</strong> Kết nối ho&agrave;n hảo với Galaxy Buds, Galaxy Watch v&agrave; m&aacute;y t&iacute;nh bảng Galaxy Tab để tối ưu h&oacute;a hiệu suất l&agrave;m việc.</p>\r\n	</li>\r\n</ul>\r\n','Samsung Galaxy S26 là chiếc smartphone Android nhỏ gọn và mạnh mẽ nhất hiện nay. Với sự lột xác về ngôn ngữ thiết kế phẳng hiện đại, thiết bị được trang bị chip Snapdragon 8 Gen 5 cực khủng cùng hệ thống Galaxy AI 2.0 có khả năng học hỏi thói quen người dùng theo thời gian thực. Galaxy S26 không chỉ là một chiếc điện thoại, mà còn là một trợ lý thông minh toàn năng giúp bạn xử lý công việc, sáng tạo nội dung và giải trí đỉnh cao trong một lòng bàn tay.',3,3,'2026-04-22 15:57:54','2026-04-23 13:44:03','1','1','1',1,1,'?en Onyx, X?m Marble, T?m Cobalt, V?ng Amber','128GB, 256GB, 512GB'),(8,5,'Oppo Reno15 Pro+','oppo-reno15-pro','reno15-1.jpg','reno15-1.jpg',19900000,16910000,55,0,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.78 inch, AMOLED 1.5K, 120Hz, tỷ lệ hiển thị 94%</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Qualcomm Snapdragon 8 Gen 4 (Tiến tr&igrave;nh 3nm)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Bộ nhớ</strong></td>\r\n			<td>RAM 12GB/16GB; ROM 256GB/512GB</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera sau</strong></td>\r\n			<td>Ch&iacute;nh 50MP (Sony LYT-808) + Tele Periscope 50MP (Zoom 3x) + G&oacute;c rộng 50MP</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera trước</strong></td>\r\n			<td>50MP AF (Lấy n&eacute;t tự động theo mắt)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Pin &amp; Sạc</strong></td>\r\n			<td>5.200 mAh; Sạc nhanh SuperVOOC 120W, Sạc kh&ocirc;ng d&acirc;y 50W</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hệ điều h&agrave;nh</strong></td>\r\n			<td>ColorOS 16 (Dựa tr&ecirc;n Android 16)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Kh&aacute;ng nước</strong></td>\r\n			<td>IP68/IP69</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của Oppo Reno15 Pro+</strong></h2>\r\n\r\n<h3><strong>Hệ thống Camera &quot;Chuy&ecirc;n gia ch&acirc;n dung AI&quot;</strong></h3>\r\n\r\n<p>Reno15 Pro+ n&acirc;ng tầm nhiếp ảnh di động với cảm biến ch&iacute;nh cao cấp từ Sony v&agrave; ống k&iacute;nh tiềm vọng (Periscope) lần đầu ti&ecirc;n xuất hiện tr&ecirc;n d&ograve;ng Reno.</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Thuật to&aacute;n AI Portrait:</strong> Tự động t&aacute;ch nền, xử l&yacute; &aacute;nh s&aacute;ng studio v&agrave; l&agrave;m đẹp tự nhi&ecirc;n nhưng vẫn giữ được chi tiết bề mặt da.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Chụp đ&ecirc;m si&ecirc;u n&eacute;t:</strong> Khả năng thu s&aacute;ng cải thiện 35%, gi&uacute;p những bức ảnh chụp trong điều kiện thiếu s&aacute;ng trở n&ecirc;n rực rỡ v&agrave; &iacute;t nhiễu hạt.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3><strong>Thiết kế mỏng nhẹ, sang trọng</strong></h3>\r\n\r\n<p>Oppo tiếp tục duy tr&igrave; thế mạnh về ngoại h&igrave;nh với mặt lưng k&iacute;nh được xử l&yacute; bằng c&ocirc;ng nghệ <strong>OPPO Glow</strong> thế hệ mới, tạo hiệu ứng thay đổi m&agrave;u sắc theo g&oacute;c nh&igrave;n v&agrave; chống b&aacute;m v&acirc;n tay tuyệt đối. Độ mỏng ấn tượng chỉ 7.6mm gi&uacute;p cảm gi&aacute;c cầm nắm cực kỳ thoải m&aacute;i v&agrave; thời thượng.</p>\r\n\r\n<h3><strong>Hiệu năng Flagship mạnh mẽ</strong></h3>\r\n\r\n<p>Với chip Snapdragon 8 Gen 4, Reno15 Pro+ kh&ocirc;ng ng&aacute;n bất kỳ tựa game nặng n&agrave;o hay c&aacute;c t&aacute;c vụ xử l&yacute; video 4K. Hệ thống tản nhiệt buồng hơi VC diện t&iacute;ch lớn gi&uacute;p m&aacute;y lu&ocirc;n m&aacute;t mẻ ngay cả khi hoạt động ở cường độ cao trong thời gian d&agrave;i.</p>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh bảo vệ mắt th&ocirc;ng minh</strong></h3>\r\n\r\n<p>M&agrave;n h&igrave;nh của m&aacute;y đạt độ s&aacute;ng tối đa l&ecirc;n tới 3000 nits, hiển thị r&otilde; n&eacute;t dưới trời nắng gắt. Đặc biệt, c&ocirc;ng nghệ điều chỉnh độ s&aacute;ng PWM 2160Hz gi&uacute;p giảm thiểu t&igrave;nh trạng mỏi mắt khi sử dụng điện thoại trong b&oacute;ng tối, bảo vệ thị lực cho người d&ugrave;ng.</p>\r\n\r\n<h3><strong>Sạc si&ecirc;u nhanh, sử dụng bền bỉ</strong></h3>\r\n\r\n<p>Chỉ cần <strong>10 ph&uacute;t</strong> để sạc từ 0% l&ecirc;n 50% pin với c&ocirc;ng nghệ SuperVOOC 120W. Vi&ecirc;n pin 5.200 mAh được t&iacute;ch hợp c&ocirc;ng nghệ &quot;Battery Health Engine&quot; gi&uacute;p tuổi thọ pin k&eacute;o d&agrave;i tr&ecirc;n 4 năm sử dụng m&agrave; vẫn giữ được hiệu suất tối ưu.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Tại sao n&ecirc;n chọn Oppo Reno15 Pro+?</strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>D&agrave;nh cho t&iacute;n đồ &quot;sống ảo&quot;:</strong> Nếu bạn y&ecirc;u th&iacute;ch việc chụp ảnh ch&acirc;n dung v&agrave; quay video TikTok chất lượng cao.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Ưu ti&ecirc;n sự mỏng nhẹ:</strong> Thiết kế thời trang, dễ d&agrave;ng bỏ t&uacute;i v&agrave; cầm nắm bằng một tay.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Trải nghiệm AI to&agrave;n diện:</strong> Hỗ trợ x&oacute;a vật thể bằng AI, t&oacute;m tắt cuộc họp v&agrave; dịch thuật thời gian thực cực kỳ th&ocirc;ng minh.</p>\r\n	</li>\r\n</ul>\r\n','Oppo Reno15 Pro+ là sự hội tụ giữa nghệ thuật thiết kế và sức mạnh công nghệ. Được mệnh danh là \"Chuyên gia chân dung thế hệ mới\", thiết bị sở hữu hệ thống camera tích hợp chip xử lý hình ảnh chuyên dụng kết hợp cùng sức mạnh từ vi xử lý Snapdragon 8 Gen 4. Với màn hình cong tràn viền 1.5K siêu mượt và công nghệ sạc siêu nhanh SuperVOOC 120W, Reno15 Pro+ không chỉ là một chiếc điện thoại, mà còn là một món phụ kiện thời trang đẳng cấp dành cho những người trẻ dẫn đầu xu hướng.',3,3,'2026-04-22 15:57:54','2026-05-15 23:33:42','1','1','1',1,1,'Xanh dương đậm, Hồng nhạt, Xanh dương nhạt','256GB, 512GB'),(9,1,'iPhone 17e','iphone-17e','ip17e-1.jpg','ip17e-1.jpg',17090000,14520000,80,0,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.1 inch, Super Retina XDR OLED, k&iacute;nh Ceramic Shield 2</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Apple A19 (Tiến tr&igrave;nh 3nm N3P)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Bộ nhớ trong</strong></td>\r\n			<td>Khởi điểm từ <strong>256GB</strong> (hỗ trợ tối đa 512GB)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>RAM</strong></td>\r\n			<td>8GB (Tối ưu cho Apple Intelligence)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera sau</strong></td>\r\n			<td>48MP Fusion Camera, hỗ trợ quay video 4K Dolby Vision 60fps</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Modem kết nối</strong></td>\r\n			<td>Apple C1X (Modem 5G ch&iacute;nh chủ Apple)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>T&iacute;nh năng mới</strong></td>\r\n			<td>N&uacute;t T&aacute;c vụ (Action Button), Hỗ trợ sạc MagSafe 15W</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>M&agrave;u sắc</strong></td>\r\n			<td>Đen, Trắng, Hồng Phai (Soft Pink)</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của iPhone 17e</strong></h2>\r\n\r\n<h3><strong>Sức mạnh từ Chip A19 v&agrave; Apple Intelligence</strong></h3>\r\n\r\n<p>D&ugrave; l&agrave; d&ograve;ng m&aacute;y gi&aacute; rẻ, iPhone 17e vẫn sở hữu con chip A19 mạnh mẽ tương tự tr&ecirc;n d&ograve;ng iPhone 17 ti&ecirc;u chuẩn. Với bộ tăng tốc AI t&iacute;ch hợp, m&aacute;y xử l&yacute; mượt m&agrave; c&aacute;c t&iacute;nh năng th&ocirc;ng minh như t&oacute;m tắt văn bản, chỉnh sửa ảnh chuy&ecirc;n nghiệp v&agrave; trợ l&yacute; Siri thế hệ mới, gi&uacute;p trải nghiệm người d&ugrave;ng trở n&ecirc;n đơn giản v&agrave; hiệu quả hơn.</p>\r\n\r\n<h3><strong>Modem C1X: Tốc độ mạng đột ph&aacute;</strong></h3>\r\n\r\n<p>iPhone 17e l&agrave; một trong những thiết bị đầu ti&ecirc;n trang bị modem 5G do ch&iacute;nh Apple thiết kế. Modem C1X kh&ocirc;ng chỉ gi&uacute;p tốc độ tải xuống nhanh hơn gấp đ&ocirc;i m&agrave; c&ograve;n cực kỳ tiết kiệm điện năng, gi&uacute;p duy tr&igrave; kết nối ổn định ngay cả ở những khu vực s&oacute;ng yếu như tầng hầm hay thang m&aacute;y.</p>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh si&ecirc;u bền với Ceramic Shield 2</strong></h3>\r\n\r\n<p>Mặt k&iacute;nh trước của iPhone 17e được n&acirc;ng cấp l&ecirc;n <strong>Ceramic Shield thế hệ 2</strong>, mang lại khả năng chống trầy xước tốt hơn gấp 3 lần so với đời cũ. Ngo&agrave;i ra, lớp phủ chống ch&oacute;i mới gi&uacute;p m&agrave;n h&igrave;nh hiển thị r&otilde; r&agrave;ng v&agrave; dễ chịu hơn khi bạn sử dụng trực tiếp dưới &aacute;nh nắng mặt trời.</p>\r\n\r\n<h3><strong>N&uacute;t T&aacute;c vụ (Action Button) đa năng</strong></h3>\r\n\r\n<p>Thay thế cho cần gạt rung truyền thống, n&uacute;t T&aacute;c vụ cho ph&eacute;p bạn c&aacute; nh&acirc;n h&oacute;a thao t&aacute;c nhanh: mở camera, bật đ&egrave;n pin, ghi &acirc;m hoặc chạy c&aacute;c ph&iacute;m tắt (Shortcuts) chỉ với một lần nhấn. Đ&acirc;y l&agrave; sự n&acirc;ng cấp đ&aacute;ng gi&aacute; gi&uacute;p tối ưu h&oacute;a th&oacute;i quen sử dụng h&agrave;ng ng&agrave;y.</p>\r\n\r\n<h3><strong>Dung lượng lưu trữ gấp đ&ocirc;i</strong></h3>\r\n\r\n<p>Hiểu được nhu cầu lưu trữ ng&agrave;y c&agrave;ng cao, Apple đ&atilde; loại bỏ phi&ecirc;n bản 128GB. Giờ đ&acirc;y, iPhone 17e khởi điểm ngay từ mức <strong>256GB</strong>, cho ph&eacute;p bạn thoải m&aacute;i quay phim 4K, lưu trữ t&agrave;i liệu học tập v&agrave; ứng dụng nặng m&agrave; kh&ocirc;ng cần lo lắng về việc dọn dẹp bộ nhớ thường xuy&ecirc;n.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Tại sao bạn n&ecirc;n chọn iPhone 17e?</strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Gi&aacute; trị sử dụng cao:</strong> Cấu h&igrave;nh mạnh ngang flagship nhưng gi&aacute; th&agrave;nh lại rất cạnh tranh.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Độ bền bỉ:</strong> Kh&aacute;ng nước IP68, khung nh&ocirc;m chắc chắn v&agrave; mặt k&iacute;nh si&ecirc;u bền.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Nhỏ gọn nhưng mạnh mẽ:</strong> D&agrave;nh cho những ai y&ecirc;u th&iacute;ch cảm gi&aacute;c cầm nắm bằng một tay nhưng vẫn muốn c&oacute; hiệu năng top đầu thị trường.</p>\r\n	</li>\r\n</ul>\r\n','iPhone 17e là sự kết hợp hoàn hảo giữa thiết kế gọn nhẹ truyền thống và sức mạnh công nghệ tương lai. Được trang bị chip A19 tiên tiến cùng modem C1X do Apple tự phát triển, thiết bị mang lại hiệu năng xử lý AI vượt trội và tốc độ kết nối 5G nhanh gấp đôi thế hệ trước. Với màn hình 6.1 inch sắc nét, lớp kính Ceramic Shield 2 siêu bền và sự xuất hiện của nút Tác vụ (Action Button), iPhone 17e là lựa chọn kinh tế nhất để trải nghiệm trọn vẹn hệ sinh thái Apple Intelligence.',3,3,'2026-04-22 15:57:54','2026-04-23 13:42:03','1','1','1',1,1,'Hồng, Trắng, Đen','128GB, 256GB, 512GB'),(10,1,'iPhone 16 Pro Max 512GB','iphone-16-pro-max-512gb','ip15pm-tu-nhien.jpg','ip15pm-tu-nhien.jpg#ip15pm-den.jpg#ip15pm-trang.jpg#ip15pm-sa-mac.jpg',12900000,10900000,120,0,15,'<h2><strong>1. Th&ocirc;ng số kỹ thuật chi tiết</strong></h2>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<td><strong>Ti&ecirc;u ch&iacute;</strong></td>\r\n			<td><strong>Th&ocirc;ng số kỹ thuật</strong></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>M&agrave;n h&igrave;nh</strong></td>\r\n			<td>6.9 inch, LTPO Super Retina XDR OLED, 120Hz (ProMotion)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vi xử l&yacute;</strong></td>\r\n			<td>Apple A18 Pro (Tiến tr&igrave;nh 3nm thế hệ mới)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Bộ nhớ trong</strong></td>\r\n			<td>512GB</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Camera sau</strong></td>\r\n			<td>Ch&iacute;nh 48MP + G&oacute;c si&ecirc;u rộng 48MP + Tele 5x 12MP</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Quay phim</strong></td>\r\n			<td>4K 120 fps Dolby Vision, ProRes, Log</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Cổng kết nối</strong></td>\r\n			<td>USB-C (Tốc độ USB 3 l&ecirc;n đến 10Gb/s)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Pin</strong></td>\r\n			<td>Dung lượng lớn nhất lịch sử iPhone, hỗ trợ sạc nhanh &amp; MagSafe</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Vật liệu</strong></td>\r\n			<td>Khung Titan cấp độ 5, mặt trước Ceramic Shield thế hệ mới</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<hr />\r\n<h2><strong>2. C&aacute;c đặc điểm nổi bật của iPhone 16 Pro Max</strong></h2>\r\n\r\n<h3><strong>M&agrave;n h&igrave;nh 6.9 inch lớn nhất v&agrave; đẹp nhất</strong></h3>\r\n\r\n<p>Lần đầu ti&ecirc;n iPhone đạt đến k&iacute;ch thước m&agrave;n h&igrave;nh <strong>6.9 inch</strong> nhưng vẫn giữ được sự gọn g&agrave;ng nhờ c&ocirc;ng nghệ giảm viền mỏng kỷ lục. Độ s&aacute;ng cực cao c&ugrave;ng c&ocirc;ng nghệ Always-On Display gi&uacute;p mọi th&ocirc;ng tin lu&ocirc;n r&otilde; r&agrave;ng ngay cả dưới &aacute;nh nắng gắt.</p>\r\n\r\n<h3><strong>Chip A18 Pro: Qu&aacute;i vật hiệu năng</strong></h3>\r\n\r\n<p>Được thiết kế ri&ecirc;ng để xử l&yacute; c&aacute;c t&aacute;c vụ AI phức tạp của <strong>Apple Intelligence</strong>, chip A18 Pro kh&ocirc;ng chỉ nhanh hơn m&agrave; c&ograve;n tiết kiệm điện hơn. CPU v&agrave; GPU thế hệ mới cho ph&eacute;p chơi c&aacute;c tựa game AAA mượt m&agrave; với c&ocirc;ng nghệ Ray Tracing nhanh gấp đ&ocirc;i thế hệ cũ.</p>\r\n\r\n<h3><strong>Hệ thống Camera Pro v&agrave; n&uacute;t Camera Control</strong></h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>N&uacute;t Điều khiển Camera:</strong> Một bề mặt cảm ứng mới gi&uacute;p bạn mở camera, lấy n&eacute;t, zoom v&agrave; điều chỉnh c&aacute;c th&ocirc;ng số chụp ảnh chỉ bằng c&aacute;ch vuốt chạm tr&ecirc;n cạnh m&aacute;y.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Camera Ultra Wide 48MP:</strong> Cho ph&eacute;p chụp ảnh macro v&agrave; ảnh g&oacute;c rộng với chi tiết cực cao.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Quay phim 4K 120 fps:</strong> Lần đầu ti&ecirc;n xuất hiện, cho ph&eacute;p bạn tạo ra những thước phim chuyển động chậm (Slow-motion) mượt m&agrave; như phim nhựa Hollywood ở độ ph&acirc;n giải 4K sắc n&eacute;t.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3><strong>Lưu trữ 512GB: Kh&ocirc;ng gian của sự tự do</strong></h3>\r\n\r\n<p>Với dung lượng 512GB, bạn c&oacute; thể tự tin:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Lưu trữ h&agrave;ng chục ng&agrave;n bức ảnh chất lượng cao.</p>\r\n	</li>\r\n	<li>\r\n	<p>Quay video định dạng ProRes (định dạng chuy&ecirc;n nghiệp chiếm nhiều bộ nhớ) m&agrave; kh&ocirc;ng lo b&aacute;o đầy bộ nhớ giữa chừng.</p>\r\n	</li>\r\n	<li>\r\n	<p>C&agrave;i đặt mọi ứng dụng v&agrave; tr&ograve; chơi nặng nhất hiện nay.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3><strong>Thời lượng pin bền bỉ nhất</strong></h3>\r\n\r\n<p>Nhờ sự tối ưu của iOS 18 v&agrave; chip A18 Pro, iPhone 16 Pro Max cung cấp thời gian xem video l&ecirc;n đến <strong>33 giờ</strong>, gi&uacute;p bạn sử dụng xuy&ecirc;n suốt cả ng&agrave;y d&agrave;i với cường độ cao m&agrave; kh&ocirc;ng cần đến sạc dự ph&ograve;ng.</p>\r\n\r\n<hr />\r\n<h2><strong>3. Tại sao n&ecirc;n chọn iPhone 16 Pro Max 512GB?</strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>D&agrave;nh cho Content Creator:</strong> Nếu bạn thường xuy&ecirc;n quay TikTok, l&agrave;m Vlog hoặc chụp ảnh nghệ thuật, mức dung lượng 512GB l&agrave; &quot;điểm ngọt&quot; ho&agrave;n hảo giữa chi ph&iacute; v&agrave; nhu cầu sử dụng l&acirc;u d&agrave;i.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Trải nghiệm đỉnh cao:</strong> D&agrave;nh cho những ai muốn sở hữu chiếc điện thoại c&oacute; m&agrave;n h&igrave;nh to nhất, pin tốt nhất v&agrave; c&ocirc;ng nghệ mới nhất của Apple.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Giữ gi&aacute; tốt:</strong> C&aacute;c phi&ecirc;n bản dung lượng cao của d&ograve;ng Pro Max lu&ocirc;n giữ gi&aacute; v&agrave; dễ d&agrave;ng n&acirc;ng cấp về sau.</p>\r\n	</li>\r\n</ul>\r\n','iPhone 16 Pro Max 512GB là đỉnh cao công nghệ smartphone hiện nay, sở hữu màn hình lớn nhất từ trước đến nay cùng viền màn hình siêu mỏng đầy ấn tượng. Với chip A18 Pro đột phá và nút Điều khiển Camera (Camera Control) mới, thiết bị mang lại trải nghiệm quay phim và chụp ảnh chuẩn điện ảnh ngay trong tầm tay. Phiên bản 512GB cung cấp không gian lưu trữ cực kỳ thoải mái cho các video 4K, ảnh ProRAW và các ứng dụng nặng, là lựa chọn lý tưởng cho người dùng chuyên nghiệp và những ai yêu thích sáng tạo nội dung.',3,3,'2026-04-22 15:57:54','2026-04-23 13:40:58','1','1','1',1,1,'Titan T? Nhi?n, Titan ?en, Titan Tr?ng, Titan Xanh','256GB, 512GB, 1TB'),(11,1,'iPhone 15','iphone-15-128gb','apple-ip15-hong.jpg','apple-ip15-hong.jpg#apple-ip15-xanh-duong.jpg#apple-ip15-den.jpg',19990000,17490000,50,0,13,'<h2><strong>1. Thông số kỹ thuật chi tiết</strong></h2>\n<table class=\"table table-bordered\">\n<thead><tr><td><strong>Tiêu chí</strong></td><td><strong>Thông số kỹ thuật</strong></td></tr></thead>\n<tbody>\n<tr><td><strong>Màn hình</strong></td><td>6.1 inch, Super Retina XDR OLED, Dynamic Island</td></tr>\n<tr><td><strong>Vi xử lý (CPU)</strong></td><td>Apple A16 Bionic (4nm)</td></tr>\n<tr><td><strong>RAM</strong></td><td>6GB</td></tr>\n<tr><td><strong>Bộ nhớ trong</strong></td><td>128GB, 256GB, 512GB</td></tr>\n<tr><td><strong>Màu sắc</strong></td><td>Hồng Pastel, Xanh Lá, Vàng, Xanh Dương, Đen</td></tr>\n<tr><td><strong>Camera sau</strong></td><td>Chính 48MP + Góc siêu rộng 12MP</td></tr>\n<tr><td><strong>Pin & Sạc</strong></td><td>3349 mAh, Sạc nhanh 20W, MagSafe 15W</td></tr>\n<tr><td><strong>Hệ điều hành</strong></td><td>iOS 18 (Cập nhật lâu dài)</td></tr>\n</tbody></table>\n<hr />\n<h2><strong>2. Đặc điểm nổi bật của iPhone 15</strong></h2>\n<p>iPhone 15 chính hãn